import{_ as t,c as i,o,ae as n}from"./chunks/framework.BIhw3mML.js";const r="/oe-user-docs/assets/app-centre-pic-en.h_7MT1iP.png",a="/oe-user-docs/assets/image-filter-en.zWRwWEbw.png",s="/oe-user-docs/assets/pic-detail-en.BySfYQwf.png",l="/oe-user-docs/assets/pic-info-en.BjRLCWVV.png",c="/oe-user-docs/assets/pic-confirm-en.BApBJYiz.png",d="/oe-user-docs/assets/pic-tbd-en.hZcofh1k.png",p="/oe-user-docs/assets/pic-add-en.BlbFvt4s.png",u="/oe-user-docs/assets/pic-action-en.BkZPwDN7.png",P=JSON.parse('{"title":"Image AI Detection","description":"","frontmatter":{},"headers":[],"relativePath":"en/pic.md","filePath":"en/pic.md","lastUpdated":1766459798000}'),g={name:"en/pic.md"};function h(m,e,b,f,q,A){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="image-ai-detection" tabindex="-1">Image AI Detection <a class="header-anchor" href="#image-ai-detection" aria-label="Permalink to &quot;Image AI Detection&quot;">​</a></h1><p><strong>Version: 1.0</strong><br><strong>Release Date: January 01, 2026</strong><br><strong>Applicable to: Alert Recipients, Action Item Responsible Persons, Regional Quality/EHS Representatives, Compliance Committee Members</strong></p><h2 id="_1-role-description" tabindex="-1">1. Role Description <a class="header-anchor" href="#_1-role-description" aria-label="Permalink to &quot;1. Role Description&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Permission Scope</th><th>Entry Point</th></tr></thead><tbody><tr><td><strong>Alert/Action Item Recipient</strong></td><td>Only handle tasks assigned to themselves<br>• No access to 【Application Center】</td><td>Home → 【Pending Confirmation Alerts】<br>Home → 【Pending Action Items】</td></tr><tr><td><strong>Application Owner</strong><br>(Regional Quality/EHS Representative, Compliance Committee Member)</td><td>Can retrieve all alerts in their region<br>• Can export and analyze data</td><td>【AI Alerting Application Center】→ Sub-applications</td></tr></tbody></table><h2 id="_2-operation-guide" tabindex="-1">2. Operation Guide <a class="header-anchor" href="#_2-operation-guide" aria-label="Permalink to &quot;2. Operation Guide&quot;">​</a></h2><h3 id="_2-1-function-overview" tabindex="-1">2.1 Function Overview <a class="header-anchor" href="#_2-1-function-overview" aria-label="Permalink to &quot;2.1 Function Overview&quot;">​</a></h3><p>The system automatically retrieves image samples from business systems, and AI models will identify the following risks:</p><ul><li>Image upload timeout (such as &gt;72 hours)</li><li>Abnormal execution of critical steps (such as temperature stickers turning red, silicone gel application having breakpoints, etc.)</li><li>Poor image quality or unrecognizable images</li></ul><h3 id="_2-2-applicable-business" tabindex="-1">2.2 Applicable Business <a class="header-anchor" href="#_2-2-applicable-business" aria-label="Permalink to &quot;2.2 Applicable Business&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Business Domain</th><th>Application Name</th></tr></thead><tbody><tr><td><strong>On-site Quality</strong></td><td>Image AI-CTQ Detection</td></tr><tr><td><strong>On-site EHS</strong></td><td>Image AI-CTS Detection</td></tr><tr><td><strong>Manufacturing Department</strong></td><td>Manufacturing Image AI-CTQ Detection</td></tr></tbody></table><h3 id="_2-3-main-interface" tabindex="-1">2.3 Main Interface <a class="header-anchor" href="#_2-3-main-interface" aria-label="Permalink to &quot;2.3 Main Interface&quot;">​</a></h3><p>Access path: 【Alert Application Center】 → 【Image AI Detection Application】</p><p><img src="'+r+'" alt="Image List Page"></p><h3 id="_2-4-filtering-and-querying" tabindex="-1">2.4 Filtering and Querying <a class="header-anchor" href="#_2-4-filtering-and-querying" aria-label="Permalink to &quot;2.4 Filtering and Querying&quot;">​</a></h3><p>Supports filtering by the following conditions:</p><ul><li>Alert item number, time, status</li><li>Step upload time, belonging region, work order number, step description, project code</li><li>AI monitoring model (such as &quot;temperature sticker&quot;) etc.</li></ul><p><img src="'+a+'" alt="Image Class Filter Area"></p><h3 id="_2-5-alert-details-and-review" tabindex="-1">2.5 Alert Details and Review <a class="header-anchor" href="#_2-5-alert-details-and-review" aria-label="Permalink to &quot;2.5 Alert Details and Review&quot;">​</a></h3><ul><li>Click the 【View】 button on the right to enter the detail page:<br></li></ul><p><img src="'+s+'" alt="View Details Page"></p><ul><li>In the detail page, view AI alert results, work order information; click the 【View】 button to preview the corresponding image:<br></li></ul><p><img src="'+l+'" alt="View Details Page"></p><ul><li>In the 【Confirmation Information】 area: <ul><li>Select <strong>Whether Problem</strong> (Yes / No)</li><li>Fill in <strong>Confirmation Description</strong> (required)</li></ul></li></ul><p><img src="'+c+'" alt="Wait for Confirm"></p><blockquote><p>✅ When selecting &quot;Yes&quot;, click the <strong>【Process】</strong> button, the system will pop up the 【Alert Processing】 dialog box, providing the following three processing methods:</p></blockquote><h4 id="processing-method-1-pending-subsequent-processing" tabindex="-1">Processing Method 1: Pending subsequent processing <a class="header-anchor" href="#processing-method-1-pending-subsequent-processing" aria-label="Permalink to &quot;Processing Method 1: Pending subsequent processing&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Problem has been identified, but immediate rectification is not required (such as production scheduling, waiting for spare parts, planned maintenance, etc.)</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong> in the dialog box</li><li>Select <strong>&quot;Wait for Processing&quot;</strong> from the dropdown menu</li><li>Fill in supplementary notes (such as &quot;Wait until next week to sign uniformly&quot;)</li></ul></li></ul><p><img src="'+d+'" alt="Wait for Processing"></p><ul><li><strong>System Behavior</strong>: <ul><li>Alert status updates to <strong>&quot;Closed&quot;</strong></li><li>Does not generate action items</li><li>Remains in alert records for subsequent tracking</li></ul></li></ul><h4 id="processing-method-2-close-with-remark" tabindex="-1">Processing Method 2: Close with remark <a class="header-anchor" href="#processing-method-2-close-with-remark" aria-label="Permalink to &quot;Processing Method 2: Close with remark&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Problem has been resolved, no further action required, or acceptable deviation</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong></li><li>Select <strong>&quot;Close with Additional Information&quot;</strong> from the dropdown menu</li><li>Fill in supplementary notes</li><li>Can upload attachments as evidence</li></ul></li><li><strong>System Behavior</strong>: <ul><li>Alert status changes to <strong>&quot;Closed&quot;</strong></li><li>Does not create action items</li><li>Counted in &quot;Valid Alerts - Closed Loop&quot; statistics, used for quality analysis</li></ul></li></ul><p><img src="'+p+'" alt="Close with Additional Information"></p><h4 id="processing-method-3-add-actions" tabindex="-1">Processing Method 3: Add actions <a class="header-anchor" href="#processing-method-3-add-actions" aria-label="Permalink to &quot;Processing Method 3: Add actions&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Need to specify responsible person, corrective measures and completion deadline (such as rework, repair, process optimization, etc.)</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong></li><li>Select <strong>&quot;Add Action Item&quot;</strong> from the dropdown menu</li><li>Fill in measures, responsible person, expected completion time</li><li>Can upload attachments (such as communication records, standard templates)</li></ul></li><li><strong>System Behavior</strong>: <ul><li>Automatically generates a <strong>【Pending Closed Loop Action Item】</strong></li><li>Automatically assigns to current user (or can specify other responsible persons)</li><li>Pushes notification to responsible person&#39;s homepage</li><li>Action item status tracked independently, supports uploading rectification evidence and audit closure</li></ul></li></ul><p><img src="'+u+'" alt="Add Action Item"></p><blockquote><p>🔍 <strong>Notes</strong>:</p><ul><li>&quot;Attachments&quot; support multiple file uploads (JPG, PNG, PDF, DOCX, etc.), single file ≤20MB</li><li>All submitted content (including processing method, description, attachments) are permanently recorded, supporting audit tracing</li><li>Once submitted, processing method cannot be changed; if adjustment needed, please contact application owner to initiate modification process</li></ul></blockquote><hr><h3 id="example-scenarios" tabindex="-1">Example Scenarios <a class="header-anchor" href="#example-scenarios" aria-label="Permalink to &quot;Example Scenarios&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Actual Scenario</th><th>Recommended Processing Method</th><th>Description</th></tr></thead><tbody><tr><td>Blurry image but operation normal, re-uploaded</td><td>Close with Additional Information</td><td>Quick closure</td></tr><tr><td>Found silicone gel application breakpoint, requires rework</td><td>Add Action Item</td><td>Create task, assign engineer</td></tr><tr><td>Temperature sticker turned red, but equipment under planned maintenance</td><td>Wait for Processing</td><td>Explain maintenance situation</td></tr></tbody></table><blockquote><p>🔍 <strong>Notes</strong>:<br> The above three processing methods apply to <strong>Image, Document, APQP</strong> all alert types, ensuring flexible, compliant, and traceable problem response paths.</p></blockquote><h2 id="_3-operation-path-reference" tabindex="-1">3. Operation Path Reference <a class="header-anchor" href="#_3-operation-path-reference" aria-label="Permalink to &quot;3. Operation Path Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Alert/Action Item Recipient</th><th>Application Owner</th></tr></thead><tbody><tr><td>Review Alert</td><td>Home →【Pending Confirmation Alerts】</td><td>Application Center → Sub-application → View Alert Items</td></tr><tr><td>Close Action Item</td><td>Home →【Pending Closed Loop Action Items】</td><td>Application Center → Sub-application → View Action Items</td></tr><tr><td>Export Data</td><td>❌ Not Supported</td><td>✅ Supported (Excel, CSV)</td></tr><tr><td>Global Search</td><td>❌ Not Supported</td><td>✅ Filter by region/project, etc.</td></tr></tbody></table><h2 id="_4-frequently-asked-questions-faq" tabindex="-1">4. Frequently Asked Questions (FAQ) <a class="header-anchor" href="#_4-frequently-asked-questions-faq" aria-label="Permalink to &quot;4. Frequently Asked Questions (FAQ)&quot;">​</a></h2><p><strong>Q: Why can&#39;t I see a certain alert on my homepage?</strong><br> A: The alert is not assigned to you. Please confirm whether the belonging work order/project is within your responsibility scope.</p><p><strong>Q: Can application owner review on behalf of recipient?</strong><br> A: Not recommended. The system follows the principle of &quot;who receives, who reviews&quot; to ensure accountability.</p><p><strong>Q: What is the difference between &quot;AI-CTS&quot; and &quot;AI-CTQ&quot; in image category?</strong><br> A:</p><ul><li><strong>CTQ</strong> (Critical to Quality): Focuses on product quality critical points</li><li><strong>CTS</strong> (Critical to Safety): Focuses on personnel/environment safety critical points</li></ul><p><strong>Q: How to request application center permissions?</strong><br> A: Contact system administrator, provide role proof.</p><blockquote><p>🔍 <strong>More Questions</strong>: See the <a href="/oe-user-docs/en/faq">FAQ document</a></p></blockquote>',49)])])}const w=t(g,[["render",h]]);export{P as __pageData,w as default};
